// src/lib/kit/catalogShim.ts
var builtins = () => new Map(BUILTIN_PRODUCTS.map((p) => [p.id, p]));
var byId = builtins();
var useCatalog = {
  getState: () => ({ byId })
};
function withProducts(products, fn) {
  const map = builtins();
  for (const p of products) if (p && typeof p.id === "string" && !map.has(p.id)) map.set(p.id, p);
  const prev = byId;
  byId = map;
  try {
    return fn();
  } finally {
    byId = prev;
  }
}

