var CATEGORIES = kinds_default.categories;
function isBuiltin(id) {
  return BUILTIN_IDS.has(id);
}
function getProduct(id) {
  return useCatalog.getState().byId.get(id);
}
function missingProduct(id) {
  return {
    id,
    kind: "base",
    variant: "missing",
    category: "cabinets",
    brand: "Unavailable",
    name: "Unavailable product",
    code: "\u2014",
    widthIn: 24,
    depthIn: 24,
    heightIn: 36,
    elevationIn: 0,
    price: 0,
    finishes: [{ id: "missing", name: "Unavailable", hex: "#d9d4cb", material: "paint" }],
    blurb: "This product is no longer listed or hasn\u2019t loaded yet. It stays in your kitchen where you put it.",
    source: "missing"
  };
}
function itemWidth(item, product) {
  return item.widthIn ?? product.widthIn;
}
function productCode(product, width) {
  const byWidth = product.skuByWidth?.[String(width)];
  if (byWidth) return byWidth;
  return (product.sku || product.code).replace("{w}", String(width));
}
function priceFor(product, width) {
  const byWidth = product.priceByWidth?.[String(width)];
  if (typeof byWidth === "number" && Number.isFinite(byWidth)) return byWidth;
  if (!product.widthOptions) return product.price;
  const ratio = width / product.widthIn;
  return Math.round(product.price * (0.45 + 0.55 * ratio) / 5) * 5;
}
var isOpening = (p) => p.kind === "window" || p.kind === "door";
var hasCountertop = (p) => p.source !== "missing" && (p.kind === "base" || p.kind === "corner" || p.kind === "island" || p.kind === "sink" || p.kind === "dishwasher" || p.kind === "wine");

